import{_ as a,c as t,o as n,ag as l}from"./chunks/framework.CQuhCYrb.js";const m=JSON.parse('{"title":"Usage - Nextcloud","description":"","frontmatter":{"title":"Usage - Nextcloud"},"headers":[],"relativePath":"general/usage-nextcloud.md","filePath":"general/usage-nextcloud.md","lastUpdated":null}'),o={name:"general/usage-nextcloud.md"};function d(i,e,c,r,s,u){return n(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="usage-nextcloud" tabindex="-1">Usage - Nextcloud <a class="header-anchor" href="#usage-nextcloud" aria-label="Permalink to &quot;Usage - Nextcloud&quot;">​</a></h1><h3 id="apple" tabindex="-1">Apple <a class="header-anchor" href="#apple" aria-label="Permalink to &quot;Apple&quot;">​</a></h3><p>This works for macOS and iOS devices.</p><p>The following apps can sync with NextCloud instead of or along with iCloud: - Files - Download the NextCloud App - Contacts - Go to Settings &gt; Contacts &gt; Accounts &gt; Add Account &gt; Add CardDAV Account - Recommend you disable iCloud contact sync - Calendar - Go to Settings &gt; Calendar &gt; Accounts &gt; Add Account &gt; Add CalDAV Account - Enable Calendar and Reminder Sync - Recommend you disable iCloud Calendar and Reminder sync - Reminder - See Calendar Instructions</p><h3 id="android" tabindex="-1">Android <a class="header-anchor" href="#android" aria-label="Permalink to &quot;Android&quot;">​</a></h3><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><ul><li><p>Files</p></li><li><p>&#39; Open File Manager &gt; Connect to Server &gt; <code>davs://example.com/nextcloud/remote.php/dav/files/USERNAME/</code></p></li><li><p>&#39; Mount drive from terminal: <a href="https://docs.nextcloud.com/server/latest/user_manual/en/files/access_webdav.html#creating-webdav-mounts-on-the-linux-command-line" target="_blank" rel="noreferrer">https://docs.nextcloud.com/server/latest/user_manual/en/files/access_webdav.html#creating-webdav-mounts-on-the-linux-command-line</a></p></li><li><ul><li>Contacts</li></ul></li><li><p>&#39; Go to Settings &gt; Contacts &gt; Accounts &gt; Add Account &gt; Add CardDAV Account.</p></li><li><p>&#39; Recommend you disable iCloud contact sync.</p></li><li><p>Calendar</p></li><li><p>&#39; Go to Settings &gt; Calendar &gt; Accounts &gt; Add Account &gt; Add CalDAV Account</p></li><li><p>&#39; Enable Calendar and Reminder Sync</p></li><li><p>Recommend you disable iCloud Calendar and Reminder sync</p></li><li><p>Reminder</p><ul><li>See Calendar Instructions</li></ul></li></ul>',8)])])}const g=a(o,[["render",d]]);export{m as __pageData,g as default};
